import sys, json, random
sys.path.insert(0, '/workspace/tmp/t')
from harness import *

def naive(frames, overlap_reject, max_stream_data, max_data, crypto_limit, is_crypto):
    """frames: list of (offset, bytes) ; returns ('ERR', code) or dict of results"""
    data = {}
    highest = 0
    for off, b in frames:
        end = off + len(b)
        if is_crypto:
            if end > crypto_limit:
                return ('ERR', 'CRYPTO_BUFFER_EXCEEDED')
        else:
            if end > max_stream_data:
                return ('ERR', 'FLOW_CONTROL_ERROR')
            if highest_delta := None: pass
        # overlap check
        for i in range(len(b)):
            o = off + i
            if o in data and data[o] != b[i]:
                if overlap_reject:
                    return ('ERR', 'PROTOCOL_VIOLATION')
        for i in range(len(b)):
            o = off + i
            if o not in data:
                data[o] = b[i]
        highest = max(highest, end)
    # contiguous prefix
    p = 0
    while p in data:
        p += 1
    prefix = bytes(data[i] for i in range(p))
    return ('OK', highest, prefix.hex())

random.seed(1234)
fails = 0
for trial in range(60):
    overlap = random.choice(['reject', 'first'])
    lim = random.choice([8, 16, 64, 65536])
    is_crypto = random.choice([True, False])
    nframes = random.randint(1, 8)
    frames = []
    spec_frames = []
    for i in range(nframes):
        off = random.randint(0, 20)
        ln = random.randint(0, 6)
        b = bytes(random.randrange(256) for _ in range(ln))
        frames.append((off, b))
        spec_frames.append(CR(off, b.hex()) if is_crypto else ST(0, off, b.hex()))
    exp = naive(frames, overlap == 'reject', lim if not is_crypto else 65536, 10**18, lim, is_crypto)
    if is_crypto:
        evs = [dg(i + 1, [pk("I", i, [f])]) for i, f in enumerate(spec_frames)]
        got, _ = run(d1(evs, overlap=overlap, crypto_limit=lim))
        r = got['results'][0]
        c = r['crypto'][0]
        last = r['packets'][-1]
        if exp[0] == 'ERR':
            ok = (last['status'] == 'error' and last['reason'] == exp[1])
            res = ('ERR', exp[1])
            gotres = (last['status'], last['reason'])
            ok = gotres == ('error', exp[1])
            # state must be from before the failing frame: recompute naive on prefix
            exp2 = naive(frames[:-1], overlap == 'reject', 65536, 10**18, lim, True)
            ok = ok and (c['highest'], c['contiguous_hex']) == (exp2[1], exp2[2])
        else:
            ok = all(p['status'] == 'accepted' for p in r['packets']) and (c['highest'], c['contiguous_hex']) == (exp[1], exp[2])
    else:
        evs = [key(0, "A", "install")] + [dg(i + 1, [pk("A", i, [f])]) for i, f in enumerate(spec_frames)]
        got, _ = run(d1(evs, overlap=overlap, max_stream_data=lim))
        r = got['results'][0]
        last = r['packets'][-1]
        st = r['streams'][0] if r['streams'] else None
        if exp[0] == 'ERR':
            exp2 = naive(frames[:-1], overlap == 'reject', lim, 10**18, lim, False)
            ok = (last['status'], last['reason']) == ('error', exp[1])
            if exp2[1] == 0 and exp2[2] == '' and st is None:
                pass
            else:
                ok = ok and st is not None and (st['highest'], st['delivered_hex']) == (exp2[1], exp2[2])
        else:
            ok = all(p['status'] == 'accepted' for p in r['packets']) and st is not None and (st['highest'], st['delivered_hex']) == (exp[1], exp[2])
    if not ok:
        fails += 1
        print('FAIL trial', trial, 'overlap', overlap, 'lim', lim, 'crypto', is_crypto)
        print('  frames', [(o, b.hex()) for o, b in frames])
        print('  exp', exp)
        print('  got', json.dumps(r)[:800])
print('done, fails =', fails)
